#!/usr/bin/env python3
"""Generate docs-data.js for the static methodology_v2 documentation viewer.

Scans src/**.md and emits `window.MANIFEST` (nav metadata) + `window.DOCS`
(path -> raw markdown). The viewer (index.html + app.js) reads only that file, so
the whole thing works offline over file:// with no server.

    python3 build.py

Run it whenever you edit a doc under src/.
"""
import json
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
SRC = os.path.join(HERE, "src")
OUT = os.path.join(HERE, "docs-data.js")

GROUP_ORDER = ["(root)", "architecture", "modules", "reference", "design", "logs"]


def first_h1(text, fallback):
    for line in text.splitlines():
        s = line.strip()
        if s.startswith("# "):
            return s[2:].strip()
    return fallback


def main():
    if not os.path.isdir(SRC):
        sys.exit("no src/ directory at %s" % SRC)

    manifest, docs = [], {}
    for root, _dirs, files in os.walk(SRC):
        for fn in files:
            if not fn.endswith(".md"):
                continue
            full = os.path.join(root, fn)
            rel = os.path.relpath(full, SRC).replace(os.sep, "/")
            group = rel.split("/")[0] if "/" in rel else "(root)"
            with open(full, encoding="utf-8") as f:
                text = f.read()
            docs[rel] = text
            manifest.append({
                "path": rel,
                "group": group,
                "name": fn,
                "title": first_h1(text, fn),
            })

    # stable order: by group rank, then path
    def rank(m):
        g = m["group"]
        return (GROUP_ORDER.index(g) if g in GROUP_ORDER else 99, m["path"])
    manifest.sort(key=rank)

    payload = (
        "/* AUTO-GENERATED by build.py — do not edit by hand. Edit src/*.md then rerun. */\n"
        "window.MANIFEST = " + json.dumps(manifest, ensure_ascii=False, indent=0) + ";\n"
        "window.DOCS = " + json.dumps(docs, ensure_ascii=False) + ";\n"
    )
    with open(OUT, "w", encoding="utf-8") as f:
        f.write(payload)

    by_group = {}
    for m in manifest:
        by_group[m["group"]] = by_group.get(m["group"], 0) + 1
    print("wrote %s" % os.path.relpath(OUT, HERE))
    print("  %d pages, %d bytes" % (len(manifest), len(payload)))
    for g in sorted(by_group, key=lambda x: GROUP_ORDER.index(x) if x in GROUP_ORDER else 99):
        print("    %-14s %d" % (g, by_group[g]))


if __name__ == "__main__":
    main()
